import { cp, access } from "node:fs/promises";
import { resolve } from "node:path";

const root = process.cwd();
const output = resolve(root, "dist");

for (const directory of ["cisco", "reef", "assets"]) {
  const source = resolve(root, directory);
  try {
    await access(source);
    // Merge legacy trees without replacing pages already generated by Astro.
    // This lets individual routes migrate incrementally while all untouched
    // legacy files continue to be copied into the static output.
    await cp(source, resolve(output, directory), {
      recursive: true,
      force: false,
      errorOnExist: false,
    });
    console.log(`Preserved legacy route/assets where no migrated page exists: /${directory}/`);
  } catch (error) {
    if (error && typeof error === "object" && "code" in error && error.code !== "ENOENT") {
      throw error;
    }
  }
}
